/**
 * Repairs variant-character pollution in src/shared/freq-common.json.
 * The list was generated by simp→trad conversion using CEDICT first-entry
 * order, which sometimes picks a rare variant (岛→㠀 instead of 島).
 * Majority vote: for each simplified char, the traditional form used by the
 * MOST CEDICT entries wins; every list entry is remapped char-wise.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
const req = createRequire(import.meta.url);
const raw = req("cedict-json");
const arr = (Array.isArray(raw) ? raw : raw.entries ?? []);

// simp char -> Map(trad -> count)
const votes = new Map();
for (const e of arr) {
  const s = [...e.simplified], t = [...e.traditional];
  if (s.length !== t.length) continue;
  for (let i = 0; i < s.length; i++) {
    // identity pairs vote too — the identical form IS the standard variant
    // (differing-only voting let rare variants win: 咊 over 和)
    let m = votes.get(s[i]);
    if (!m) votes.set(s[i], (m = new Map()));
    m.set(t[i], (m.get(t[i]) ?? 0) + (s[i] === t[i] ? 5 : 1));
  }
}
// trad char -> majority trad for its simp form (self if none)
const remap = new Map();
for (const [simp, m] of votes) {
  const best = [...m.entries()].sort((a, b) => b[1] - a[1])[0][0];
  for (const trad of m.keys()) if (trad !== best) remap.set(trad, best);
}
const list = JSON.parse(readFileSync("src/shared/freq-common.json", "utf8"));
const fixed = [...new Set(list.map((w) => [...w].map((c) => remap.get(c) ?? c).join("")))];
let changed = 0;
for (let i = 0; i < fixed.length; i++) if (fixed[i] !== list[i]) changed++;
writeFileSync("src/shared/freq-common.json", JSON.stringify(fixed, null, 0) + "\n");
console.log(`entries: ${list.length} → ${fixed.length}, remapped variants: ${remap.size} rules, ${changed} entries changed`);
